## Bug Analysis

In SQL, `col IN (1, 2, NULL)` does **not** match rows where `col IS NULL` because `NULL = NULL` evaluates to `UNKNOWN`, not `TRUE`. The correct SQL must be:
- `IN`: `(col IN (1, 2) OR col IS NULL)`
- `NOT IN`: `(col NOT IN (1, 2) AND col IS NOT NULL)` — because `col NOT IN (1, 2, NULL)` returns no rows at all due to NULL propagation.

The bug is in `_build_condition` which blindly passes NULLs as `?` placeholders instead of extracting them into `IS NULL`/`IS NOT NULL` clauses.

## Fixed Code

```python
"""SQL query builder with support for complex WHERE clauses."""
from typing import Any, List, Optional, Union, Tuple
from enum import Enum
from dataclasses import dataclass, field

class Op(Enum):
    EQ = "="
    NE = "!="
    LT = "<"
    GT = ">"
    LTE = "<="
    GTE = ">="
    LIKE = "LIKE"
    IN = "IN"
    NOT_IN = "NOT IN"
    IS_NULL = "IS NULL"
    IS_NOT_NULL = "IS NOT NULL"
    BETWEEN = "BETWEEN"

@dataclass
class Condition:
    column: str
    op: Op
    value: Any = None

@dataclass
class ConditionGroup:
    conditions: List[Union['Condition', 'ConditionGroup']]
    logic: str = "AND"

@dataclass
class OrderBy:
    column: str
    direction: str = "ASC"

@dataclass
class JoinClause:
    table: str
    on: str
    join_type: str = "INNER"

class QueryBuilder:
    def __init__(self, table: str):
        self.table = table
        self._select: List[str] = ["*"]
        self._where: Optional[ConditionGroup] = None
        self._order_by: List[OrderBy] = []
        self._limit: Optional[int] = None
        self._offset: Optional[int] = None
        self._joins: List[JoinClause] = []
        self._group_by: List[str] = []
        self._having: Optional[ConditionGroup] = None
        self._params: List[Any] = []

    def select(self, *columns: str) -> 'QueryBuilder':
        self._select = list(columns)
        return self

    def where(self, *conditions: Union[Condition, ConditionGroup]) -> 'QueryBuilder':
        if len(conditions) == 1 and isinstance(conditions[0], ConditionGroup):
            self._where = conditions[0]
        else:
            self._where = ConditionGroup(conditions=list(conditions), logic="AND")
        return self

    def order_by(self, column: str, direction: str = "ASC") -> 'QueryBuilder':
        self._order_by.append(OrderBy(column=column, direction=direction))
        return self

    def limit(self, n: int) -> 'QueryBuilder':
        self._limit = n
        return self

    def offset(self, n: int) -> 'QueryBuilder':
        self._offset = n
        return self

    def join(self, table: str, on: str, join_type: str = "INNER") -> 'QueryBuilder':
        self._joins.append(JoinClause(table=table, on=on, join_type=join_type))
        return self

    def group_by(self, *columns: str) -> 'QueryBuilder':
        self._group_by = list(columns)
        return self

    def having(self, *conditions: Union[Condition, ConditionGroup]) -> 'QueryBuilder':
        if len(conditions) == 1 and isinstance(conditions[0], ConditionGroup):
            self._having = conditions[0]
        else:
            self._having = ConditionGroup(conditions=list(conditions), logic="AND")
        return self

    def build(self) -> Tuple[str, List[Any]]:
        self._params = []
        parts = [f"SELECT {', '.join(self._select)}"]
        parts.append(f"FROM {self.table}")

        for j in self._joins:
            parts.append(f"{j.join_type} JOIN {j.table} ON {j.on}")

        if self._where:
            where_sql = self._build_condition_group(self._where)
            parts.append(f"WHERE {where_sql}")

        if self._group_by:
            parts.append(f"GROUP BY {', '.join(self._group_by)}")

        if self._having:
            having_sql = self._build_condition_group(self._having)
            parts.append(f"HAVING {having_sql}")

        if self._order_by:
            order_parts = [f"{o.column} {o.direction}" for o in self._order_by]
            parts.append(f"ORDER BY {', '.join(order_parts)}")

        if self._limit is not None:
            parts.append(f"LIMIT {self._limit}")

        if self._offset is not None:
            parts.append(f"OFFSET {self._offset}")

        return " ".join(parts), self._params

    def _build_condition_group(self, group: ConditionGroup) -> str:
        parts = []
        for cond in group.conditions:
            if isinstance(cond, ConditionGroup):
                sub = self._build_condition_group(cond)
                parts.append(f"({sub})")
            elif isinstance(cond, Condition):
                parts.append(self._build_condition(cond))
        return f" {group.logic} ".join(parts)

    def _build_condition(self, cond: Condition) -> str:
        if cond.op == Op.IS_NULL:
            return f"{cond.column} IS NULL"
        if cond.op == Op.IS_NOT_NULL:
            return f"{cond.column} IS NOT NULL"
        if cond.op == Op.BETWEEN:
            self._params.extend(cond.value)
            return f"{cond.column} BETWEEN ? AND ?"

        if cond.op in (Op.IN, Op.NOT_IN):
            values = list(cond.value) if isinstance(cond.value, (list, tuple)) else [cond.value]

            # Partition values into non-null and null
            non_null = [v for v in values if v is not None]
            has_null = any(v is None for v in values)

            if cond.op == Op.IN:
                # (col IN (non_null...) OR col IS NULL)
                clauses = []
                if non_null:
                    placeholders = ", ".join("?" for _ in non_null)
                    self._params.extend(non_null)
                    clauses.append(f"{cond.column} IN ({placeholders})")
                if has_null:
                    clauses.append(f"{cond.column} IS NULL")
                if len(clauses) == 1:
                    return clauses[0]
                return "(" + " OR ".join(clauses) + ")"

            else:  # NOT_IN
                # NULL in NOT IN list makes the entire expression return no rows.
                # Correct: (col NOT IN (non_null...) AND col IS NOT NULL)
                clauses = []
                if non_null:
                    placeholders = ", ".join("?" for _ in non_null)
                    self._params.extend(non_null)
                    clauses.append(f"{cond.column} NOT IN ({placeholders})")
                # Always add IS NOT NULL when there was a NULL in the list,
                # OR unconditionally since NOT IN never matches NULLs anyway.
                if has_null or non_null:
                    clauses.append(f"{cond.column} IS NOT NULL")
                if len(clauses) == 1:
                    return clauses[0]
                return "(" + " AND ".join(clauses) + ")"

        self._params.append(cond.value)
        return f"{cond.column} {cond.op.value} ?"


# Helper functions
def and_(*conditions) -> ConditionGroup:
    return ConditionGroup(conditions=list(conditions), logic="AND")

def or_(*conditions) -> ConditionGroup:
    return ConditionGroup(conditions=list(conditions), logic="OR")

def eq(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.EQ, value=val)

def ne(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.NE, value=val)

def lt(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.LT, value=val)

def gt(col: str, val: Any) -> Condition:
    return Condition(column=col, op=Op.GT, value=val)

def in_(col: str, vals: List[Any]) -> Condition:
    return Condition(column=col, op=Op.IN, value=vals)

def not_in(col: str, vals: List[Any]) -> Condition:
    return Condition(column=col, op=Op.NOT_IN, value=vals)

def is_null(col: str) -> Condition:
    return Condition(column=col, op=Op.IS_NULL)

def between(col: str, low: Any, high: Any) -> Condition:
    return Condition(column=col, op=Op.BETWEEN, value=[low, high])


# ── Tests ──────────────────────────────────────────────────────────────────────

def test_in_with_nulls_failing_on_original():
    """
    Demonstrates the bug: IN clause with NULL must expand to
    (col IN (non-nulls) OR col IS NULL), not pass NULL as a bind param.
    """
    # ── Test 1: simple IN with a NULL value ──────────────────────────────────
    sql, params = (
        QueryBuilder("users")
        .where(in_("status", [1, 2, None]))
        .build()
    )
    # NULL must NOT appear as a bind parameter
    assert None not in params, (
        f"BUG: NULL leaked into params={params!r}; "
        "NULL in IN list must become IS NULL clause, not a bind param."
    )
    assert "IS NULL" in sql, f"Expected 'IS NULL' in SQL but got: {sql}"
    assert "status IN" in sql,  f"Expected 'status IN' in SQL but got: {sql}"
    assert params == [1, 2], f"Expected params=[1, 2], got {params!r}"
    # Full shape check
    assert sql == (
        "SELECT * FROM users WHERE (status IN (?, ?) OR status IS NULL)"
    ), f"Unexpected SQL: {sql}"

    # ── Test 2: IN with ONLY NULL ────────────────────────────────────────────
    sql2, params2 = (
        QueryBuilder("orders")
        .where(in_("ref", [None]))
        .build()
    )
    assert None not in params2
    assert sql2 == "SELECT * FROM orders WHERE ref IS NULL", f"Got: {sql2}"
    assert params2 == []

    # ── Test 3: NOT IN with NULL values ──────────────────────────────────────
    # col NOT IN (1, 2, NULL) in raw SQL matches NOTHING because of NULL
    # propagation. Correct form: (col NOT IN (1, 2) AND col IS NOT NULL)
    sql3, params3 = (
        QueryBuilder("users")
        .where(not_in("status", [1, 2, None]))
        .build()
    )
    assert None not in params3, f"NULL leaked into params: {params3!r}"
    assert "IS NOT NULL" in sql3, f"Expected IS NOT NULL in: {sql3}"
    assert sql3 == (
        "SELECT * FROM users WHERE (status NOT IN (?, ?) AND status IS NOT NULL)"
    ), f"Got: {sql3}"
    assert params3 == [1, 2]

    # ── Test 4: IN with NULL nested inside an OR group ───────────────────────
    sql4, params4 = (
        QueryBuilder("products")
        .where(
            or_(
                eq("category", "electronics"),
                in_("tag", [10, None]),
            )
        )
        .build()
    )
    assert None not in params4, f"NULL leaked: {params4!r}"
    assert sql4 == (
        "SELECT * FROM products "
        "WHERE (category = ? OR (tag IN (?) OR tag IS NULL))"
    ), f"Got: {sql4}"
    assert params4 == ["electronics", 10]

    # ── Test 5: no NULLs → behaviour unchanged ───────────────────────────────
    sql5, params5 = (
        QueryBuilder("users")
        .where(in_("id", [1, 2, 3]))
        .build()
    )
    assert sql5 == "SELECT * FROM users WHERE id IN (?, ?, ?)"
    assert params5 == [1, 2, 3]

    print("All tests passed.")


if __name__ == "__main__":
    test_in_with_nulls_failing_on_original()
```

### Key changes in `_build_condition`

| Scenario | Generated SQL |
|---|---|
| `IN([1, 2, None])` | `(col IN (?, ?) OR col IS NULL)` — params: `[1, 2]` |
| `IN([None])` | `col IS NULL` — params: `[]` |
| `IN([1, 2])` | `col IN (?, ?)` — params: `[1, 2]` (unchanged) |
| `NOT IN([1, 2, None])` | `(col NOT IN (?, ?) AND col IS NOT NULL)` — params: `[1, 2]` |
| `NOT IN([1, 2])` | `(col NOT IN (?, ?) AND col IS NOT NULL)` — always guards IS NOT NULL because `NOT IN` never matches NULLs |

The fix separates `None` values from the bind-parameter list and converts them into `IS NULL` / `IS NOT NULL` predicates, joined with the appropriate logical operator and wrapped in parentheses for safe embedding inside any outer `AND`/`OR` group.
